import { io } from "socket.io-client";
// import { store } from "@/store/index.js";
// 创建socket实例（注意：生产环境应使用HTTPS）
export const socket = io("http://localhost:2525", {
  autoConnect: true,
  transports: ["websocket"],
});
export function socket_connect(){
  socket.on("connect", () => {
    console.log("连接成功");
  });
}
export function socket_disconnect(){
  socket.on("disconnect", () => {
    console.log("断开连接");
  });
}
export default {
socket_connect,socket_disconnect
};
